package io.bmsride.monitor;
import android.Manifest;import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.bluetooth.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
@SuppressWarnings("MissingPermission") public class MainActivity extends Activity {
 final int BG=0xff09141f,CARD=0xff152b3b,FG=0xffe9f6ff,MUT=0xff8da8ba,TEAL=0xff65dfc4,BLUE=0xff3498ff; final Handler h=new Handler(); MonitorService service; boolean bound; LinearLayout body; TextView status,stats,cellText; Meter meter; int tab=0; LinearLayout deviceRows; TextView deviceCount; ArrayList<String> renderedDevices=new ArrayList<>(); 
 final ServiceConnection connection=new ServiceConnection(){public void onServiceConnected(ComponentName n,IBinder b){service=((MonitorService.Local)b).service();draw();}public void onServiceDisconnected(ComponentName n){service=null;}};
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);draw();permissions();h.post(refresh);}
 void permissions(){ArrayList<String> p=new ArrayList<>();p.add(Manifest.permission.ACCESS_FINE_LOCATION);p.add(Manifest.permission.ACCESS_COARSE_LOCATION);if(Build.VERSION.SDK_INT>=31){p.add(Manifest.permission.BLUETOOTH_SCAN);p.add(Manifest.permission.BLUETOOTH_CONNECT);}if(Build.VERSION.SDK_INT>=33)p.add(Manifest.permission.POST_NOTIFICATIONS);ArrayList<String> missing=new ArrayList<>();for(String s:p)if(checkSelfPermission(s)!=PackageManager.PERMISSION_GRANTED)missing.add(s);if(missing.isEmpty())start();else requestPermissions(missing.toArray(new String[0]),42);}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED&&(Build.VERSION.SDK_INT<31||checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT)==PackageManager.PERMISSION_GRANTED&&checkSelfPermission(Manifest.permission.BLUETOOTH_SCAN)==PackageManager.PERMISSION_GRANTED))start();else Toast.makeText(this,"需要精确定位和附近设备权限",Toast.LENGTH_LONG).show();}
 void start(){if(bound)return;Intent i=new Intent(this,MonitorService.class);startForegroundService(i);bound=bindService(i,connection,BIND_AUTO_CREATE);}
 int dp(int x){return (int)(getResources().getDisplayMetrics().density*x+0.5f);} TextView txt(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(dp(12),dp(8),dp(12),dp(8));return t;}
 GradientDrawable bg(int color){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(14));return g;}
 void button(String label,Runnable r){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextColor(FG);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(CARD));b.setOnClickListener(v->r.run());body.addView(b);}
 void draw(){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(10),dp(8),dp(10),dp(8));root.setBackgroundColor(BG);setContentView(root);root.addView(txt("BMS 随行20",25,TEAL));LinearLayout nav=new LinearLayout(this);for(int i=0;i<4;i++){final int j=i;TextView t=txt(new String[]{"总览","行车 GPS","电芯","设备"}[i],14,i==tab?TEAL:MUT);t.setGravity(17);t.setOnClickListener(v->{tab=j;draw();});nav.addView(t,new LinearLayout.LayoutParams(0,dp(44),1));}root.addView(nav);status=txt("等待权限",13,MUT);root.addView(status);ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));stats=null;cellText=null;meter=null;deviceRows=null;deviceCount=null;renderedDevices.clear();
 if(tab<2){meter=new Meter(this);body.addView(meter,new LinearLayout.LayoutParams(-1,dp(205)));stats=txt("—",20,FG);stats.setBackground(bg(CARD));body.addView(stats);if(tab==1){button("开始 GPS",()->{if(service!=null)service.enableGps();});button("暂停 GPS",()->{if(service!=null)service.disableGps();});button("重置里程/能耗",()->{if(service!=null)service.resetTrip();});}}
 else if(tab==2){cellText=txt("等待20串数据",19,FG);cellText.setTypeface(Typeface.MONOSPACE);cellText.setBackground(bg(CARD));body.addView(cellText);}
 else{TextView model=txt("保锂安 LK8625",20,TEAL);model.setBackground(bg(CARD));body.addView(model);EditText cap=new EditText(this);cap.setHint("手动满充容量 Ah（可留空）");cap.setInputType(8194);if(service!=null&&Double.isFinite(service.capacityOverride))cap.setText(String.valueOf(service.capacityOverride));body.addView(cap);button("保存容量（估算备用）",()->{if(service==null)return;try{String s=cap.getText().toString().trim();double x=s.isEmpty()?Double.NaN:Double.parseDouble(s);if(!s.isEmpty()&&(!Double.isFinite(x)||x<=0||x>2000))throw new IllegalArgumentException();service.setCapacity(x);}catch(Exception e){Toast.makeText(this,"请输入有效 Ah 或留空",Toast.LENGTH_SHORT).show();}});button("扫描 BLE 设备",()->{if(service!=null){service.setDemo(false);service.ble.scan();}});deviceCount=txt("已发现 0 台 BLE 设备 · 上下滑动选择",14,MUT);body.addView(deviceCount);deviceRows=new LinearLayout(this);deviceRows.setOrientation(LinearLayout.VERTICAL);body.addView(deviceRows,new LinearLayout.LayoutParams(-1,-2));updateDevices();button("断开 BMS",()->{if(service!=null)service.setDemo(false);});button("开启/退出演示模式",()->{if(service!=null)service.setDemo(!service.demo);});button("停止监测服务",()->{if(bound){unbindService(connection);bound=false;}stopService(new Intent(this,MonitorService.class));service=null;finish();});} }
 // The page ScrollView is the sole vertical scroller. No fixed-height nested list.
 void updateDevices(){
  if(deviceRows==null||service==null)return;
  ArrayList<BluetoothDevice> now=new ArrayList<>(service.ble.devices.values());
  ArrayList<String> labels=new ArrayList<>();
  for(BluetoothDevice d:now){String name=d.getName();labels.add((name==null||name.trim().isEmpty()?"未知设备":name)+"\n"+d.getAddress());}
  deviceCount.setText("已发现 "+now.size()+" 台 BLE 设备 · 上下滑动选择");
  if(labels.equals(renderedDevices))return;
  renderedDevices=labels;deviceRows.removeAllViews();
  for(int i=0;i<now.size();i++){
   final BluetoothDevice d=now.get(i);TextView row=txt(labels.get(i),16,FG);
   row.setMinHeight(dp(60));row.setGravity(Gravity.CENTER_VERTICAL);row.setBackground(bg(CARD));
   LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(6);
   deviceRows.addView(row,lp);row.setFocusable(true);row.setOnClickListener(v->{if(service!=null){service.demo=false;service.ble.connect(d,Protocol.Kind.BAOLIAN);}});
  }
 }
 String probe(JSONObject j){JSONArray a=j.optJSONArray("temps");if(a==null||a.length()==0)return "T1 —  T2 —  T3 —";StringBuilder s=new StringBuilder();for(int i=0;i<a.length();i++){double x=a.optDouble(i,Double.NaN);s.append("T").append(i+1).append(" ").append(Double.isFinite(x)?String.format(Locale.US,"%.1f°C",x):"—").append("  ");}return s.toString();}
 String flags(JSONObject j){int x=j.optInt("mosFlags",-1);if(x<0)return "MOS 状态：未知";return "充电MOS "+((x&64)!=0?"开":"关")+" / 放电MOS "+((x&128)!=0?"开":"关")+" / 预放电 "+((x&32)!=0?"开":"关")+"\n原始告警/保护/故障："+j.optString("alarm","—")+" / "+j.optString("protection","—")+" / "+j.optString("fault","—");}
 String f(JSONObject j,String key,int dec){double n=j.optDouble(key,Double.NaN);return Double.isFinite(n)?String.format(Locale.US,"%."+dec+"f",n):"—";}
 final Runnable refresh=new Runnable(){public void run(){if(service!=null){JSONObject j=service.snapshot();status.setText((service.demo?"演示 · ":"")+service.status);if(meter!=null){meter.j=j;meter.invalidate();}if(stats!=null)stats.setText(tab==0?"总电压  "+f(j,"voltage",2)+" V\n电池电流  "+f(j,"current",2)+" A\n实时功率  "+f(j,"power",0)+" W\n剩余容量（保锂安估算）  "+f(j,"ah",2)+" Ah\n电池温度  "+f(j,"temp",1)+" °C\nMOS 温度  "+f(j,"mos",1)+" °C\n电芯压差  "+f(j,"delta",3)+" V\n"+probe(j)+"\n"+flags(j):"累计里程  "+f(j,"km",2)+" km\n平均耗电  "+f(j,"eff",1)+" Wh/km\n预计续航  "+f(j,"range",0)+" km（估算）\nGPS 精度  "+f(j,"accuracy",0)+" m");if(cellText!=null){JSONArray a=j.optJSONArray("cells");StringBuilder s=new StringBuilder("20 串电芯 · Δ "+f(j,"delta",3)+" V\n\n");double min=99,max=0;if(a!=null&&a.length()==20){for(int i=0;i<20;i++){min=Math.min(min,a.optDouble(i));max=Math.max(max,a.optDouble(i));}}for(int i=0;i<20;i++){double n=a!=null?a.optDouble(i,Double.NaN):Double.NaN;s.append(String.format(Locale.US,"%02d  %s %s   ",i+1,Double.isFinite(n)?String.format(Locale.US,"%.3f",n):"—",n==min?"↓":n==max?"↑":" "));if(i%2==1)s.append('\n');}cellText.setText(s.toString());}updateDevices();}h.postDelayed(this,500);}};
 class Meter extends View{JSONObject j=new JSONObject();Paint p=new Paint(3);Meter(Context c){super(c);}protected void onDraw(Canvas c){float w=getWidth(),hh=getHeight(),cx=w/2,cy=hh*.55f,r=Math.min(w*.39f,hh*.45f);String key=tab==0?"soc":"speed";double n=j.optDouble(key,Double.NaN);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(12));p.setStrokeCap(Paint.Cap.ROUND);RectF a=new RectF(cx-r,cy-r,cx+r,cy+r);p.setColor(CARD);c.drawArc(a,145,250,false,p);p.setColor(tab==0?TEAL:BLUE);if(Double.isFinite(n))c.drawArc(a,145,(float)(250*Math.min(1,Math.max(0,n/(tab==0?100:80)))),false,p);p.setStyle(Paint.Style.FILL);p.setTextAlign(Paint.Align.CENTER);p.setTextSize(dp(51));p.setColor(FG);c.drawText(f(j,key,0),cx,cy+dp(10),p);p.setTextSize(dp(17));p.setColor(MUT);c.drawText(tab==0?"% SOC":"km/h",cx,cy+dp(37),p);}}
 protected void onDestroy(){h.removeCallbacksAndMessages(null);if(bound)unbindService(connection);super.onDestroy();}
}
